import React, { useState, useCallback, useEffect } from 'react'
import { View, Text, TouchableOpacity, Dimensions, FlatList } from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

export function ShoppingCart() {
    const [numberSelectDelete, setNumberSelectDelete] = useState<number[]>([]);

    const {
        shoppingCartItem,
        selectedNumber,
        shoppingCartActive,
    } = useContexState();

    const {
        setShoppingCartItem,
        setSelectedNumber,
        setShoppingCartActive,
    } = useContexState();


    const keyExtractor = useCallback(
        (item) => item.id.toString(), []
    );

    const conta = (shoppingCartItem.length) * 19.99;
    const arredondado = parseFloat(conta.toFixed(2));
    const price = arredondado.toString().replace('.', ',');

    const result = []
    for (let i = 0; i < shoppingCartItem.length; i++) {
        result.push({ id: i, number: shoppingCartItem[i] });
    };

    function ApplyDeletion() {
        const temp = [...shoppingCartItem];
        numberSelectDelete.map(i => {
            let indice = temp.indexOf(i);
            if (shoppingCartItem[indice]) {
                while (indice >= 0) {
                    temp.splice(indice, 1);
                    indice = temp.indexOf(i);
                };
                setShoppingCartItem(temp);
                setNumberSelectDelete([]);
            };
        });
    };

    function SelectDelete(number: number) {
        const temp = [...numberSelectDelete];
        const buscar = number;
        let indice = temp.indexOf(buscar);

        if (numberSelectDelete[indice]) {
            while (indice >= 0) {
                temp.splice(indice, 1);
                indice = temp.indexOf(buscar);
            };
            setNumberSelectDelete(temp);
        } else {
            setNumberSelectDelete([...temp, number]);
        };
    };

    function Card({ number }: { number: number }) {
        const temp = [...numberSelectDelete];
        const buscar = number;
        let indice = temp.indexOf(buscar);
        return (
            <TouchableOpacity style={{ alignItems: 'flex-end' }} onPress={() => SelectDelete(number)}>
                <Text style={[styles.listText, numberSelectDelete[indice] ? { backgroundColor: '#E22222', color: '#fff' } : null]}>
                    {(`0000${number}`).slice(-4)}
                </Text>
            </TouchableOpacity>
        );
    };


    return (shoppingCartActive ? <>
        <TouchableOpacity onPress={() => {
            setShoppingCartActive(false);
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />

        <View style={styles.container} >
            <Text style={{ color: '#fff', fontSize: 20, textAlign: 'center', marginVertical: 6 }}>{`${shoppingCartItem.length} POR APENAS${"\n"}R$ ${price}`}</Text>
            <FlatList
                data={result /*result*/}
                keyExtractor={keyExtractor}
                numColumns={4}
                renderItem={({ item }) => <Card number={item.number} />}
            />

            <TouchableOpacity onPress={() => numberSelectDelete.length > 0 ? ApplyDeletion() : {}} style={[styles.buttonPay, numberSelectDelete.length > 0 ? { backgroundColor: '#E22222' } : null]} >
                <Text style={styles.payText}>{numberSelectDelete.length > 0 ? 'Excluir' : 'Pagar'}</Text>
            </TouchableOpacity>
        </View>
    </> : null
    );
};



